<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Service\Visibility\TemplateVariableVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariable;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVariableCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVariableVisibilityService $visibility,
        private readonly TemplateVariableWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for Template variable");
        $span = $this->startSpan("Check allow of create usecase for Template variable");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVariableCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(TemplateVariableCreateParams $params): TemplateVariableCreateResult
    {
        $this->logDebug("Run create usecase for Template variable");
        $span = $this->startSpan("Run create usecase for Template variable");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create Template variable');
            }
            $this->dispatcher->dispatch(new TemplateVariableCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new TemplateVariableCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = TemplateVariable::create($input);
            $result = $this->writer->create(
                $entity,
                fn (TemplateVariable $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateVariableCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
